node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey } from './src/billing/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
assert.deepEqual(answer.call_chain.map(({symbol}) => symbol), ['checkout', 'submitInvoice', 'makeReceiptKey', 'sendInvoice']);
for (const {file, symbol} of answer.call_chain) {
  const module = await import(`./${file}`);
  assert.equal(typeof module[symbol], 'function');
}
assert.equal(answer.owner_file, answer.call_chain[2].file);
assert.equal(answer.owner_symbol, answer.call_chain[2].symbol);
assert.equal(answer.outbound_file, answer.call_chain[3].file);
assert.equal(answer.outbound_symbol, answer.call_chain[3].symbol);
const invoice = { accountId: 'acme', sequence: 7 };
assert.equal(makeReceiptKey(invoice), answer.example_key);
let sent = 0;
const provider = { post(path, body, headers) {
  sent++;
  assert.equal(path, '/invoices');
  assert.equal(body, invoice);
  assert.equal(headers['Idempotency-Key'], answer.example_key);
  return 'sent';
} };
assert.equal(await checkout(invoice, provider), 'sent');
assert.equal(sent, 1);
console.log('PASS: answer structure, symbols, example key and checkout outbound header');
